namespace sv_e6e583422a3846538de0cb04ca5a4a07.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> SlotsByDoctor = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:00 AM", "10:30 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (SlotsByDoctor.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }

        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient and appointment details. Returns a dictionary of field-level errors.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Simulate outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookingModel.Email)] = "Account has outstanding balance";
        }

        // Simulate self-pay restriction
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookingModel.PreferredDoctor)] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookingModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookingModel
{
    public string PatientName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string InsuranceProvider { get; set; } = string.Empty;
    public string PreferredDoctor { get; set; } = string.Empty;
    public DateOnly? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = string.Empty;
    public string ReasonForVisit { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_e6e583422a3846538de0cb04ca5a4a07.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
            @if (_serverErrors.ContainsKey(nameof(Model.PatientName)))
            {
                <div class="validation-message">@_serverErrors[nameof(Model.PatientName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (_serverErrors.ContainsKey(nameof(Model.Email)))
            {
                <div class="validation-message">@_serverErrors[nameof(Model.Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
            @if (_serverErrors.ContainsKey(nameof(Model.Phone)))
            {
                <div class="validation-message">@_serverErrors[nameof(Model.Phone)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
        }
    </fieldset>

    @* STEP 2: Appointment Details *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.PreferredDoctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
                @if (_serverErrors.ContainsKey(nameof(Model.PreferredDoctor)))
                {
                    <div class="validation-message">@_serverErrors[nameof(Model.PreferredDoctor)]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (_serverErrors.ContainsKey(nameof(Model.AppointmentDate)))
                {
                    <div class="validation-message">@_serverErrors[nameof(Model.AppointmentDate)]</div>
                }
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (_serverErrors.ContainsKey(nameof(Model.TimeSlot)))
                {
                    <div class="validation-message">@_serverErrors[nameof(Model.TimeSlot)]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-primary" @onclick="CheckAvailability">Check Availability</button>

            @if (_bookingConfirmed)
            {
                <div class="alert alert-success mt-3">Appointment booked successfully!</div>
            }
        </fieldset>
    }
</EditForm>

@code {
    private BookingModel Model { get; set; } = new();

    private bool _showStep2;
    private bool _bookingConfirmed;
    private List<string> _doctors = [];
    private List<string> _availableSlots = [];
    private Dictionary<string, string> _serverErrors = new();

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields
        if (string.IsNullOrWhiteSpace(Model.PatientName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            !IsValidEmail(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            _serverErrors.Clear();

            if (string.IsNullOrWhiteSpace(Model.PatientName))
                _serverErrors[nameof(Model.PatientName)] = "Patient Name is required.";
            if (string.IsNullOrWhiteSpace(Model.Email))
                _serverErrors[nameof(Model.Email)] = "Email is required.";
            else if (!IsValidEmail(Model.Email))
                _serverErrors[nameof(Model.Email)] = "Email format is invalid.";
            if (string.IsNullOrWhiteSpace(Model.Phone))
                _serverErrors[nameof(Model.Phone)] = "Phone is required.";
            if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
                _serverErrors[nameof(Model.InsuranceProvider)] = "Insurance Provider is required.";

            return;
        }

        _serverErrors.Clear();
        _showStep2 = true;
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrWhiteSpace(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            _availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.PreferredDoctor, Model.AppointmentDate.Value);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _bookingConfirmed = false;

        // Client-side validation for step 2
        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor))
            _serverErrors[nameof(Model.PreferredDoctor)] = "Please select a doctor.";
        if (!Model.AppointmentDate.HasValue)
            _serverErrors[nameof(Model.AppointmentDate)] = "Date is required.";
        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            _serverErrors[nameof(Model.AppointmentDate)] = "Date must be in the future.";
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            _serverErrors[nameof(Model.TimeSlot)] = "Please select a time slot.";
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason for visit is required.";
        else if (Model.ReasonForVisit.Length > 500)
            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason must be 500 characters or less.";

        if (_serverErrors.Count > 0)
            return;

        // Server-side validation
        var validationResult = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (validationResult.Count > 0)
        {
            _serverErrors = validationResult;
            return;
        }

        _bookingConfirmed = true;
    }

    private Task HandleSubmit()
    {
        return Task.CompletedTask;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

