@code {
    private BookingModel Model { get; set; } = new();

    private bool _showStep2;
    private bool _bookingConfirmed;
    private List<string> _doctors = [];
    private List<string> _availableSlots = [];
    private Dictionary<string, string> _serverErrors = new();

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields
        if (string.IsNullOrWhiteSpace(Model.PatientName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            !IsValidEmail(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            _serverErrors.Clear();

            if (string.IsNullOrWhiteSpace(Model.PatientName))
                _serverErrors[nameof(Model.PatientName)] = "Patient Name is required.";
            if (string.IsNullOrWhiteSpace(Model.Email))
                _serverErrors[nameof(Model.Email)] = "Email is required.";
            else if (!IsValidEmail(Model.Email))
                _serverErrors[nameof(Model.Email)] = "Email format is invalid.";
            if (string.IsNullOrWhiteSpace(Model.Phone))
                _serverErrors[nameof(Model.Phone)] = "Phone is required.";
            if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
                _serverErrors[nameof(Model.InsuranceProvider)] = "Insurance Provider is required.";

            return;
        }

        _serverErrors.Clear();
        _showStep2 = true;
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrWhiteSpace(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            _availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.PreferredDoctor, Model.AppointmentDate.Value);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _bookingConfirmed = false;

        // Client-side validation for step 2
        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor))
            _serverErrors[nameof(Model.PreferredDoctor)] = "Please select a doctor.";
        if (!Model.AppointmentDate.HasValue)
            _serverErrors[nameof(Model.AppointmentDate)] = "Date is required.";
        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            _serverErrors[nameof(Model.AppointmentDate)] = "Date must be in the future.";
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            _serverErrors[nameof(Model.TimeSlot)] = "Please select a time slot.";
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason for visit is required.";
        else if (Model.ReasonForVisit.Length > 500)
            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason must be 500 characters or less.";

        if (_serverErrors.Count > 0)
            return;

        // Server-side validation
        var validationResult = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (validationResult.Count > 0)
        {
            _serverErrors = validationResult;
            return;
        }

        _bookingConfirmed = true;
    }

    private Task HandleSubmit()
    {
        return Task.CompletedTask;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

